(function(){'use strict';
const {q,source:S,finite:F,answer:A,scaled:AS}=window.MT_PRACTICE_BANK,pi=Math.PI,rad=pi/180;
// Chapter 13 — signed compass corrections, plane sailing and spherical geometry.
q(13,1,'Compass to magnetic','Compass heading is 350° and deviation is +5° east. Find magnetic heading.',355,'°','East deviation is positive in Hmag=Hcomp+dev.', ['Hmag = wrap360(350+5)','Hmag = 355°'],S('book-c13-p185-r01',{H_comp:350,dev:5}));
q(13,2,'Magnetic to true','Magnetic heading is 358° and variation is +7° east. Find true heading in [0,360).',5,'°','Add east variation, then wrap past north.', ['Htrue = wrap360(358+7)','365° wraps to 5°'],S('book-c13-p185-r02',{H_mag:358,'var':7}));
q(13,3,'Latitude change','A vessel moves from latitude 58°N to 60°N. Find signed change of latitude in degrees.',2,'°','North latitude is positive in this signed calculation.', ['Δφ = φ₂−φ₁','Δφ = 60−58'],S('book-c13-p186-r02',{'φ₂':60,'φ₁':58}));
q(13,4,'Plane-sailing distance','Northing is 30 NM and easting is 40 NM in a local plane-sailing approximation. Find distance.',50,'NM','Use the right triangle formed by northing and easting.', ['d = √(DLat²+Dep²)','d = √(30²+40²)'],S('book-c13-p189-r07',{DLat:30,Dep:40}));
q(13,5,'Northing','A local plane-sailing leg is 100 NM at true course 60°. Find northing.',50,'NM','Course is measured clockwise from north, so northing uses cosine.', ['DLat = d cosC','DLat = 100cos60°'],S('book-c13-p189-r02',{d:100,C:60},{degrees:true}));
q(13,6,'Easting','A local plane-sailing leg is 100 NM at true course 30°. Find easting.',50,'NM','Course is measured from north, so departure uses sine.', ['Dep = d sinC','Dep = 100sin30°'],S('book-c13-p189-r03',{d:100,C:30},{degrees:true}));
q(13,7,'Date-line difference','Longitudes are 179°E and 179°W. Taking east positive, find the shortest signed longitude change from the first to the second.',2,'°','Represent west as negative, then wrap the difference to [−180,180).', ['Δλ = wrap180(−179−179)','−358° wraps to +2°'],S('book-c13-p188-r01',{'λ₂':-179,'λ₁':179}));
q(13,8,'Passage duration','At constant speed 12 kn over distance 90 NM, find elapsed passage time.',7.5,'h','One knot is one nautical mile per hour.', ['t = d/v','t = 90/12'],F('quotient',{numerator:90,denominator:12}));
q(13,9,'Reverse compass correction','True heading is 3°, variation +8° east and deviation −2° west. Find compass heading.',357,'°','Subtract both signed corrections before wrapping.', ['Hcomp = wrap360(Htrue−var−dev)','Hcomp = wrap360(3−8−(−2))'],S('book-c13-p185-r03',{H_true:3,'var':8,dev:-2}));
q(13,10,'Departure to longitude','At mean latitude 60°, a local departure is 30 NM east. Estimate longitude change in degrees by plane sailing.',1,'°','One degree of longitude corresponds locally to 60cosφ NM.', ['Δλ ≈ Dep/(60cosφm)','Δλ ≈ 30/(60×0.5)'],S('book-c13-p189-r05',{Dep:30,'φ_m':60},{degrees:true}));
q(13,11,'Radian central angle','On a spherical Earth of radius 6371 km, two points subtend central angle 0.1 rad. Find great-circle distance.',637.1,'km','Distance equals radius times central angle in radians.', ['d = Rσ','d = 6371×0.1'],S('book-c13-p191-r02',{R:6371,'σ':.1}));
q(13,12,'Rhumb-course quadrant','A spherical rhumb calculation gives Δλ=−0.02 rad and Δψ=0.02. Find normalized course in radians.',7*pi/4,'rad','atan2 takes east–west change first and meridional change second; wrap to [0,2π).', ['atan2(−0.02,0.02) = −π/4','C = wrap2π(−π/4) = 7π/4'],S('book-c13-p190-r03',{'Δλ':-.02,'Δψ':.02}));
q(13,13,'Great-circle separation','Two points on a sphere are both at latitude 60°N and differ by 60° longitude. Find the shorter central angle in radians.',Math.acos(.875),'rad','Use spherical geometry; a constant-latitude arc is not generally a great circle.', ['cosσ = sin²60°+cos²60°cos60° = 0.875','σ = acos(0.875)'],S('book-c13-p191-r01',{'φ₁':pi/3,'φ₂':pi/3,'Δλ':pi/3,'σ':A},{compareSides:true}));
q(13,14,'Local hour angle','GHA is 350° and longitude is 20° east. Convert both to radians and find LHA in radians normalized to [0,2π).',10*rad,'rad','East-positive longitude is added to GHA in this convention.', ['GHA+λ = 370°','LHA = wrap2π(370π/180) = 10π/180'],S('book-c13-p194-r01',{GHA:350*rad,'λ':20*rad}));
q(13,15,'Celestial altitude','At latitude 30°N, declination 0° and local hour angle 60°, find geometrical altitude in radians, neglecting refraction.',Math.asin(Math.sqrt(3)/4),'rad','Keep every angle in radians within the spherical altitude relation.', ['sinh = sinφ sinδ+cosφ cosδ cosH = cos30°cos60°','h = asin(√3/4)'],S('book-c13-p192-r08',{'φ':30*rad,'δ':0,H:60*rad,h:A},{compareSides:true}));
q(13,16,'Eight-heading compass interpolation','At headings 0°,45°,…,315°, deviations are 1,3,2,0,−1,1,2,0 degrees. Fit the eight-point model A+Σ[Bk sin(kθ)+Ck cos(kθ)] for k=1…3, plus Kcos(4θ). Find its interpolated deviation at 22.5°.',1+Math.SQRT2/4*(Math.sin(pi/8)+Math.sin(3*pi/8))+(2+Math.SQRT2)/4*Math.cos(pi/8)+(2-Math.SQRT2)/4*Math.cos(3*pi/8),'°','Use A=Σdj/8, Bk=Σdj sin(kθj)/4, Ck=Σdj cos(kθj)/4 and K=Σdj cos(4θj)/8.', ['A=1, B₁=B₃=√2/4, C₁=(2+√2)/4, B₂=1, C₂=−1, C₃=(2−√2)/4, K=0.','At θ=π/8, the second-harmonic terms cancel. Evaluate the remaining first- and third-harmonic terms.'],F('compassInterpolation8',{deviations:[1,3,2,0,-1,1,2,0],angle:pi/8}));
// Chapter 14 — hydrostatic definitions before free surface, lifting and trim.
q(14,1,'Density-corrected displacement','A hydrostatic table gives 10000 t at reference density 1.025 t/m³. At the same immersed volume and actual density 1.000 t/m³, find displacement.',10000/1.025,'t','Displacement at a fixed immersed volume scales with water density.', ['Δ = Δtable ρ/ρtable','Δ = 10000×1.000/1.025'],S('book-c14-p195-r01',{'Δ_table':10000,'ρ':1,'ρ_table':1.025}));
q(14,2,'Waterplane area','Length is 100 m, breadth 20 m and waterplane coefficient 0.8. Find waterplane area.',1600,'m²','The coefficient scales the surrounding rectangle.', ['Aw = L B Cwp','Aw = 100×20×0.8'],S('book-c14-p196-r07',{L:100,B:20,C_wp:.8}));
q(14,3,'TPC','Waterplane area is 1600 m² and water density is 1.025 t/m³. Find tonnes per centimetre immersion.',16.4,'t/cm','A one-centimetre draft increase is 0.01 m.', ['TPC = ρAw/100','TPC = 1.025×1600/100'],S('book-c14-p197-r04',{'ρ':1.025,A_w:1600}));
q(14,4,'Small-angle righting lever','For an illustrative vessel with effective GM=1.0 m and heel 5°, use GZ≈GM sinθ. Find righting lever.',Math.sin(5*rad),'m','Use the stated small-angle model; this is not a full cross-curve calculation.', ['GZ ≈ GMeff sinθ','GZ ≈ 1.0sin5°'],S('book-c14-p198-r01',{GM:1,'θ':5*rad}));
q(14,5,'Existing weight shift','A 100 t weight already aboard is moved upward by 5 m on a 10000 t vessel. Find rise of centre of gravity.',.05,'m','Existing weight remains in the original displacement.', ['GG = wd/Δ','GG = 100×5/10000'],S('book-c14-p196-r01',{w:100,d:5,'Δ':10000}));
q(14,6,'New load KG','A vessel has displacement 10000 t and KG=5 m. Load 1000 t at kg=10 m. Find new KG.',60/11,'m','Both vertical moment and displacement increase.', ['KGnew = (ΔKG+wkg)/(Δ+w)','KGnew = (10000×5+1000×10)/11000'],S('book-c14-p196-r02',{'Δ':10000,KG:5,w:1000,kg_i:10}));
q(14,7,'Tank free-surface inertia','A slack rectangular tank has free-surface length 10 m and transverse breadth 4 m. Find transverse free-surface second moment of area.',160/3,'m⁴','Transverse breadth is the cubed dimension.', ['IFS = lb³/12','IFS = 10×4³/12'],S('book-c14-p196-r05',{l_tank:10,b_tank:4}));
q(14,8,'Mean sinkage','Load 164 t on a vessel with locally constant TPC=16.4 t/cm. Find mean sinkage before trim effects.',10,'cm','Use the supplied local TPC linearization.', ['δTcm ≈ w/TPC','δTcm ≈ 164/16.4'],S('book-c14-p209-r01',{w:164,TPC:16.4}));
q(14,9,'Free-surface correction','One slack tank has liquid density 0.8 t/m³ and free-surface inertia 500 m⁴. Vessel displacement is 10000 t. Find the small-angle free-surface correction.',.04,'m','Use tank-liquid density with vessel displacement mass; subtract this correction from GM.', ['FSC = ρl IFS/Δ','FSC = 0.8×500/10000'],S('book-c14-p196-r04',{'ρ_l':.8,I_FS:500,'Δ':10000}));
q(14,10,'Inclining experiment','An illustrative test shifts 20 t transversely by 10 m on a 10000 t vessel. Measured tanθ=0.02. Find effective GM.',1,'m','The moment balance uses tangent of heel, not the angle in degrees.', ['GMeff = wd/(Δtanθ)','GMeff = 20×10/(10000×0.02)'],S('book-c14-p198-r05',{w:20,d:10,'Δ':10000,'θ':Math.atan(.02)}));
q(14,11,'Trim from weight shift','An existing 50 t weight moves 20 m aft. With MCT=100 t·m/cm and aft-positive trim, find change of trim.',10,'cm','Existing weight shift creates a moment without adding displacement.', ['δtrim = w(xnew−xold)/MCT','δtrim = 50×20/100'],S('book-c14-p207-r07',{w:50,x_new:20,x_old:0,MCT:100}));
q(14,12,'Cross-curve lever','At one specified displacement, trim and heel 30°, supplied KN=3.0 m and effective KG=5.0 m. Find GZ for zero TCG.',.5,'m','Use KN for the stated loading condition, then subtract KG sinθ.', ['GZ = KN−KGeff sinθ','GZ = 3−5×0.5'],S('book-c14-p198-r03',{KN:3,KG_eff:5,'θ':30*rad}));
q(14,13,'Suspended onboard load','A 100 t load already aboard a 10000 t vessel moves from z=3 m to a suspension hook at z=13 m. Initial KG=5 m. Find new effective KG, neglecting dynamic effects.',5.1,'m','For an onboard load, use the vertical shift to the suspension point and unchanged displacement.', ['ΔKG = 100(13−3)/10000 = 0.1 m','KGnew = 5+0.1'],S('book-c14-p199-r02',{KG:5,w:100,z_hook:13,z_old:3,'Δ':10000}));
q(14,14,'New suspended load TCG','A vessel initially has displacement 10000 t and TCG=0. A new 100 t suspended load is supported at signed transverse coordinate +10 m. Find new TCG.',10/101,'m','A load arriving from outside the vessel adds both mass and transverse moment.', ['Δnew = 10100 t','TCGnew = (10000×0+100×10)/10100'],S('book-c14-p200-r03',{'Δ':10000,TCG:0,w:100,y_hook:10}));
q(14,15,'Added counterweight and onboard lift','Initial displacement is 10000 t and KG=5 m. An onboard 100 t load rises 10 m; a NEW 200 t counterweight is added at z=2 m. Find new effective KG. Ignore free surface and dynamics.',257/51,'m','The onboard lift changes moment only; the new counterweight also changes displacement.', ['Vertical moment = 10000×5+100×10+200×2 = 51400 t·m','KGnew = 51400/10200 = 257/51 m'],S('book-c14-p202-r02',{'Δ':10000,KG:5,w:100,z_hook:13,z_old:3,c:200,z_c:2}));
q(14,16,'End drafts with off-centre LCF','A new load of 100 t is placed at x=20 m aft of midships. L=100 m, LCF=10 m aft, TPC=20 t/cm and MCT=100 t·m/cm, treated constant. Find aft draft increase in cm.',9,'cm','Compute trim about LCF, then add sinkage and the aft-end share of trim.', ['δtrim = 100(20−10)/100 = 10 cm; sinkage=100/20=5 cm','δTA = 5+10(50−10)/100 = 9 cm'],[S('book-c14-p208-r03',{w:100,x:20,LCF:10,MCT:100},{expected:10}),S('book-c14-p209-r02',{w:100,TPC:20,'δtrim_cm':10,L:100,LCF:10})]);
// Chapter 15 — explicitly defined cash-flow timing, rates and discounted sums.
q(15,1,'Simple payback','An investment costs 10000 currency units and saves 2500 per year at a constant rate. Ignoring discounting, find simple payback.',4,'years','Simple payback ignores both discounting and cash flows after recovery.', ['n = I₀/A','n = 10000/2500'],S('book-c15-p219-r05',{'I₀':10000,A:2500}));
q(15,2,'Periodic nominal rate','A nominal annual rate of 12% is convertible monthly. Find the monthly rate as a fraction.',.01,'','Divide the quoted nominal annual rate by the number of conversion periods.', ['r = rnom/m','r = 0.12/12'],S('book-c15-p220-r05',{r_nom:.12,m_periods:12}));
q(15,3,'Effective annual rate','A deposit earns 1% each month, compounded monthly. Find effective annual rate as a fraction.',1.01**12-1,'','Compound all twelve monthly periods.', ['reff = (1+r)^m−1','reff = 1.01¹²−1'],S('book-c15-p221-r02',{r:.01,m_periods:12}));
q(15,4,'Real rate','Nominal annual return is 8% and annual inflation is 3%. Find the exact real annual rate as a fraction.',1.08/1.03-1,'','Use the ratio of growth factors, rather than subtracting the percentages.', ['r = (1+i)/(1+π)−1','r = 1.08/1.03−1'],S('book-c15-p219-r01',{i:.08,'π_infl':.03}));
q(15,5,'Single-payment present value','One payment of 1100 is received at the end of year 1. At discount rate 10%, find its present value.',1000,'currency units','Discount the future payment by one growth factor.', ['PV = 1100/(1+0.10)','PV = 1000'],F('discountedCashFlows',{flows:[1100],rate:.1}));
q(15,6,'Annuity present value','Receive 1000 at each year-end for three years. Discount at 10% annually. Find present value.',1000*(1/1.1+1/1.1**2+1/1.1**3),'currency units','The first payment is one year away; discount each of the three payments.', ['PV = 1000/1.1+1000/1.1²+1000/1.1³','Equivalent ordinary-annuity factor: [1−1.1⁻³]/0.1.'],S('book-c15-p220-r01',{A:1000,r:.1,n:3}));
q(15,7,'Net present value','An outlay of 2000 occurs now, followed by receipts of 1000 at each year-end for three years. At 10%, find NPV.',1000*(1/1.1+1/1.1**2+1/1.1**3)-2000,'currency units','Subtract the time-zero investment after discounting future receipts.', ['PVreceipts = 2486.85199','NPV = PVreceipts−2000'],S('book-c15-p219-r03',{A:1000,r:.1,n:3,'I₀':2000}));
q(15,8,'Equal-principal payment','A loan has original principal 12000, 12 equal principal repayments and 1% interest per period. Find the FIRST total payment, before any repayment.',1120,'currency units','Equal-principal repayment adds interest on the outstanding balance.', ['Principal component = 12000/12 = 1000','Payment₁ = 1000+12000×0.01'],S('book-c15-p220-r04',{Loan:12000,N:12,Balance_prev:12000,r:.01}));
q(15,9,'Level loan payment','A 10000 loan is repaid by three equal year-end payments at 10% per year. Find the annual payment.',10000*.1/(1-1.1**(-3)),'currency units/year','This is an ordinary amortizing annuity with the first payment after one year.', ['A = I₀r/[1−(1+r)⁻ⁿ]','A = 10000×0.1/(1−1.1⁻³)'],S('book-c15-p220-r02',{'I₀':10000,r:.1,n:3}));
q(15,10,'NPV-to-investment convention','Under the chapter convention PI=NPV/I₀, an investment of 2000 has NPV=500. Find PI. This is not gross PV divided by investment.',.25,'','Use the explicitly stated net convention.', ['PI = NPV/I₀','PI = 500/2000'],S('book-c15-p219-r04',{NPV:500,'I₀':2000}));
q(15,11,'Discounted payback root','Initial outlay is 2000 and constant year-end benefit is 1000. At r=10%, find the continuous-period root of the annuity payback equation; it is not an actual fractional payment date.',-Math.log(.8)/Math.log(1.1),'years','Solve the discounted-annuity equation; actual annual-payment recovery occurs at the next payment.', ['n = −ln(1−I₀r/A)/ln(1+r)','n = −ln(0.8)/ln(1.1); discrete year-end payback is year 3.'],S('book-c15-p219-r06',{'I₀':2000,r:.1,A:1000}));
q(15,12,'Zero-rate present value','Receive 500 at each year-end for four years and use discount rate zero. Find present value.',2000,'currency units','At zero rate, use the finite cash-flow sum rather than divide by r.', ['PV = 500+500+500+500','PV = 4×500'],F('discountedCashFlows',{flows:[500,500,500,500],rate:0}));
q(15,13,'Inflation and escalation','Nominal discount rate is 10%, general inflation 2% and additional real cost escalation 3% annually. Under r=(1+i)/[(1+π)(1+e)]−1, find the equivalent rate.',1.1/(1.02*1.03)-1,'','The two distinct escalation factors multiply; avoid double counting the same inflation.', ['r = 1.10/(1.02×1.03)−1','Denominator = 1.0506'],S('book-c15-p219-r02',{i:.1,'π_infl':.02,e:.03}));
q(15,14,'Up-front trade discount','An invoice discount of 2% is available for earlier payment. Using 12 identical credit periods per year, find the effective annual cost of forgoing that discount.',(1/.98)**12-1,'','Each period’s financing factor is 1/(1−d), not 1+d.', ['reff = [1/(1−d)]^m−1','reff = (1/0.98)¹²−1'],S('book-c15-p221-r01',{d:.02,m_periods:12}));
q(15,15,'Uneven cash-flow NPV','Invest 2500 now and receive 1000, 1200 and 1500 at the ends of years 1,2,3. At 10%, find NPV.',1000/1.1+1200/1.1**2+1500/1.1**3-2500,'currency units','Unequal annual benefits require separate discounting, not one annuity factor.', ['PV = 1000/1.1+1200/1.1²+1500/1.1³','NPV = PV−2500'],F('discountedCashFlows',{flows:[1000,1200,1500],rate:.1,initial:2500}));
q(15,16,'Cost of saved energy','An efficiency project has capital cost 10000, capital-recovery factor 0.12 per year, added annual cost 100, avoided demand charge 300 and annual energy saved 5000 kWh. Find cost of saved energy.',.2,'currency units/kWh','Annualize capital, add extra annual costs, then subtract avoided demand cost.', ['Annual net cost = 10000×0.12+100−300 = 1000','Csave = 1000/5000'],S('book-c15-p221-r03',{'I₀':10000,CRF:.12,'ΔC_annual':100,B_demand:300,E_saved:5000}));
// Chapter 16 — survey geometry, density, tank inventory and cargo accounting.
q(16,1,'Port and starboard mean','At one draft station, port reading is 5.20 m and starboard reading is 5.40 m. Find station mean.',5.3,'m','Average the paired readings at the same longitudinal station.', ['Tstation = (TP+TS)/2','Tstation = (5.20+5.40)/2'],S('book-c16-p222-r01',{T_P:5.2,T_S:5.4}));
q(16,2,'Signed trim','Forward draft at perpendicular is 5.0 m and aft draft is 6.0 m. With aft-minus-forward convention, find trim.',1,'m','Use perpendicular drafts with the same reference datum.', ['trim = TA−TF','trim = 6.0−5.0'],S('book-c16-p223-r02',{T_A:6,T_F:5}));
q(16,3,'End mean draft','Forward and aft perpendicular drafts are 5.0 and 6.0 m. Find their arithmetic mean.',5.5,'m','This is the end mean; it does not yet include hull-deflection correction.', ['Tmean = (TF+TA)/2','Tmean = (5.0+6.0)/2'],S('book-c16-p223-r03',{T_F:5,T_A:6}));
q(16,4,'Tank ullage volume','A tank capacity is 1000 m³ and loaded volume is 920 m³. Find ullage volume.',80,'m³','Ullage here is unfilled volume, not a measured vertical distance.', ['Vullage = Vtank−Vload','Vullage = 1000−920'],S('book-c14-p212-r01',{V_tank:1000,V_load:920}));
q(16,5,'Mark correction','Use aft-positive x. A draft mark at x=0 reads 5.0 m. The target is at x=10 m; signed trim between marks is +1.0 m over Lmarks=100 m. Find target draft by linear correction.',5.1,'m','Use the target-minus-mark longitudinal offset and the signed trim slope.', ['Ttarget = Tmark+(xtarget−xmark)trim/Lmarks','Ttarget = 5.0+10×1.0/100'],S('book-c16-p222-r03',{T_mark:5,x_target:10,x_mark:0,trim_marks:1,L_marks:100}));
q(16,6,'Survey density correction','Table displacement is 10000 t at 1.025 t/m³. At the same equivalent immersed volume, measured water density is 1.010 t/m³. Find actual displacement.',10000*1.01/1.025,'t','Apply the actual-to-reference density ratio once.', ['Δactual = Δtable ρactual/ρtable','Δactual = 10000×1.010/1.025'],S('book-c16-p224-r01',{'Δ_table':10000,'ρ_actual':1.01,'ρ_table':1.025}));
q(16,7,'Ullage percent','A 1000 m³ tank has 80 m³ ullage volume. Find ullage percentage.',8,'%','Divide unfilled volume by tank capacity, not by loaded volume.', ['Pullage = 100 Vullage/Vtank','Pullage = 100×80/1000'],S('book-c14-p212-r02',{V_ullage:80,V_tank:1000}));
q(16,8,'Standard volume','Observed liquid volume is 1000 m³ and a supplied valid volume-correction factor to 15 °C is 0.98. Find standard volume.',980,'m³ at 15 °C','The VCF is supplied for this liquid and temperature; it is not a universal thermal coefficient.', ['V15 = Vobs VCF','V15 = 1000×0.98'],S('book-c14-p211-r01',{V_obs:1000,VCF:.98}));
q(16,9,'Hull-deflection adjustment','End mean draft is 6.0 m and corrected midship draft is 5.7 m. Under the chapter survey convention δT=(Tmean−TM)/3, find δT.',.1,'m','Keep the sign of the end-mean minus midship difference.', ['δT = (6.0−5.7)/3','δT = 0.1 m'],S('book-c16-p223-r04',{T_mean:6,T_M:5.7}));
q(16,10,'Equivalent draft','Corrected midship draft is 5.7 m and the chapter deflection adjustment is +0.1 m. Find equivalent draft.',5.8,'m','Add the signed deflection correction to midship draft.', ['Tequiv = TM+δT','Tequiv = 5.7+0.1'],S('book-c16-p223-r05',{T_M:5.7,'δT':.1}));
q(16,11,'Draft at LCF','Using aft-positive coordinates, equivalent draft is 5.8 m, LCF is +5 m, length 100 m and aft-minus-forward trim +1 m. Find approximate draft at LCF.',5.85,'m','Use the longitudinal trim slope and signed LCF position.', ['TLCF ≈ Tequiv+(LCF/L)trim','TLCF ≈ 5.8+(5/100)×1'],S('book-c16-p223-r06',{T_equiv:5.8,LCF:5,L:100,trim:1}));
q(16,12,'Cargo mass from standard volume','Gross standard liquid volume is 980 m³ and supplied density at 15 °C is 0.85 t/m³. Find mass, neglecting air-buoyancy correction.',833,'t','Standard volume and density must use the same reference temperature.', ['m = GSV ρ15','m = 980×0.85'],S('book-c14-p211-r07',{GSV:980,'ρ_15':.85}));
q(16,13,'Transfer inventory correction','Tank volume rises from 200 to 700 m³. A separate documented thermal expansion accounts for +10 m³ of the change. Find transferred volume on this common observed basis.',490,'m³','Remove inventory change caused by the separately identified non-transfer effect.', ['Vtransferred = Vafter−Vbefore−Vnontransfer','Vtransferred = 700−200−10'],S('book-c14-p211-r06',{V_after:700,V_before:200,V_nontransfer_changes:10}));
q(16,14,'Loading limit by VCF','A 1000 m³ tank must retain margin 0.02 at the limiting warm condition. Supplied valid VCFmax=0.96 and VCFload=0.99. Find maximum volume at the loading condition.',1000*.98*.96/.99,'m³','Conserve standard volume between loading and the limiting warm condition.', ['V15,max = 1000(1−0.02)×0.96','Vload,max = V15,max/0.99'],S('book-c14-p211-r04',{V_tank:1000,p_margin:.02,VCF_max:.96,VCF_load:.99}));
q(16,15,'Draft-survey cargo balance','Density-corrected arrival displacement is 10000 t and departure displacement is 12000 t. During loading, 100 t ballast was discharged and 20 t fuel was consumed; no other mass changes occurred. Find cargo loaded.',2120,'t','Cargo must replace the removed ballast and consumed fuel as well as increase displacement.', ['Δdeparture−Δarrival = cargo−100−20','cargo = 12000−10000+100+20'],F('cargoBalance',{arrival:10000,departure:12000,otherMassChanges:[-100,-20]}));
q(16,16,'Combined survey correction','Aft-positive survey data: corrected TF=5.4 m, TA=6.6 m and TM=5.7 m; L=100 m and LCF=+5 m. Apply δT=(endmean−TM)/3 and TLCF=TM+δT+(LCF/L)trim. Find TLCF.',5.86,'m','Complete end mean, deflection adjustment and LCF correction in that order.', ['End mean=6.0 m; δT=(6.0−5.7)/3=0.1 m; trim=1.2 m','TLCF = 5.7+0.1+5×1.2/100'],[S('book-c16-p223-r04',{T_mean:6,T_M:5.7},{expected:.1}),S('book-c16-p223-r06',{T_equiv:5.8,LCF:5,L:100,trim:1.2})]);
})();
